// --- 1. FUNCIÓN DE FORMATO (Venezuela) ---
function formatoVe(valor) {
  if (typeof valor !== 'number') {
    try {
      valor = parseFloat(String(valor).replace(',', '.'));
    } catch (e) {
      return "0,00";
    }
  }

  if (isNaN(valor)) return "0,00";

  return valor.toLocaleString('es-VE', {
    minimumFractionDigits: 2,
    maximumFractionDigits: 2
  });
}

// --- 2. FUNCIÓN DE FECHA ---
function formatoFecha(fechaStr) {
  try {
    const fechaLimpia = String(fechaStr).substring(0, 10);
    const partes = fechaLimpia.split('-');
    if (partes.length === 3) {
      return partes[2] + '/' + partes[1] + '/' + partes[0];
    }
    return fechaLimpia;
  } catch (e) {
    return String(fechaStr);
  }
}

// --- 3. CONSTRUCCIÓN DEL MENSAJE ---
for (const item of items) {
  const datos = item.json;

  const fecha    = datos['Dia'] ?? '';
  const tasaDol  = datos['Tasa USD'] ?? 0;
  const tasaEur  = datos['Tasa EUR'] ?? 0;
  const tasaP2p  = datos['Tasa USDT'] ?? 0;
  const promedio = datos['Promedio Tasa'] ?? 0;
  const val5     = datos['Tasa 5$'] ?? 0;
  const val7     = datos['Tasa 7$'] ?? 0;
  const val9     = datos['Tasa 9$'] ?? 0;
  const val4     = datos['Tasa 4$'] ?? 0;
  const val15    = datos['Tasa 15$'] ?? 0;

  // --- CONSTRUCCIÓN DEL TEXTO ---
  const mensaje =
    " *BUEN DIA JEFES ACTIVOS HOY A VENDER* \n" +
    "\n" +
    "💸 *Tasa del Día Actualizada* \n" +
    "📅 *Fecha:* " + formatoFecha(fecha) + "\n\n" +
    "📊 *REFERENCIAS OFICIALES*\n" +
    "   • 🇺🇸 *Tasa Dolar:* " + formatoVe(tasaDol) + " Bs\n" +
    "   • 🇪🇺 *Tasa Euro:* " + formatoVe(tasaEur) + " Bs\n" +
    "   • 🤝 *Tasa P2p:* " + formatoVe(tasaP2p) + " Bs\n" +
    "   •  *Promedio:* " + formatoVe(promedio) + " Bs\n\n" +
    "━━━━━━━━━━━━━━━\n\n" +
    "💵 *MONTOS CUENTAS FLUJO*\n" +
    "   • *5$* →  " + formatoVe(val5) + " Bs\n" +
    "   • *7$* →  " + formatoVe(val7) + " Bs\n" +
    "   • *9$* →  " + formatoVe(val9) + " Bs\n\n" +
    "💵 *MONTOS CUENTAS NETFLIX*\n" +
    "   • *4$* →  " + formatoVe(val4) + " Bs\n" +
    "   • *15$* →  " + formatoVe(val15) + " Bs\n" +
    "✅ _Precios válidos por el día de hoy._";

  item.json['mensaje'] = mensaje;
}

return items;

// 1. Verificación inicial: ¿Hay ítems llegando al nodo?
if (!items || items.length === 0) {
    return [{
        json: {
            mensaje_final: "⚠️ *AVISO:* En este momento no tenemos TASA del dia disponible para calcular los precios. Por favor, intenta de nuevo despues de las 8:30AM."
        }
    }];
}

// 2. Buscamos el ítem que tiene la tasa (buscamos en todos los ítems recibidos)
const itemTasa = items.find(i => i.json && i.json["Promedio Tasa"] !== undefined);

// 3. Verificación de tasa: ¿Se encontró el ítem y tiene tasa válida?
if (!itemTasa || !itemTasa.json["Promedio Tasa"]) {
    return [{
        json: {
            mensaje_final: "⚠️ *AVISO:* Aún no se ha cargado la tasa del día. Por favor, intenta de nuevo despues de las 8:30AM."
        }
    }];
}

const datosTasa = itemTasa.json;

// 4. Formateo de números (función segura)
const f = (val) => {
    const num = parseFloat(val);

    return isNaN(num)
        ? "0,00"
        : num.toLocaleString('de-DE', {
            minimumFractionDigits: 2,
            maximumFractionDigits: 2
        });
};

// 5. Armamos el mensaje final
return [{
    json: {
        mensaje_final:
        `🎬 *Promos de streaming disponibles por 1 MES*\n\n` +

        `🔸 *NETFLIX — 1 pantalla*\n` +
        `${f(datosTasa["Tasa 4$"])} Bs. / $4\n` +
        `La opción más económica si solo quieres Netflix.\n\n` +

        `🌟 *FLUJOTV — TODO en una sola aplicación*\n` +
        `+1000 canales de TV en vivo, deportes, series y películas de todas las plataformas.\n\n` +

        `🔸 *FlujoTV — 1 Pantalla Básica*\n` +
        `${f(datosTasa["Tasa 5$"])} Bs. / $5\n` +
        `Opción económica.\n\n` +

        `🔸 *FlujoTV — Cuenta VIP (3 Pantallas)*\n` +
        `${f(datosTasa["Tasa 9$"])} Bs. / $9\n` +
        `Cuenta completa solo para ti: 100% estabilidad, menos caídas y sin molestos cambios de contraseña.\n\n` +

        `🏠 Por la diferencia de precio, *FlujoTV Cuenta VIP* es la opción que más recomendamos para la casa.\n\n` +

        `¿Con cuál empezamos? 🚀`
    }
}];

const todos = items;

// Filtramos por servicio
const netflixItems = todos.filter(item => item.json.tipo_servicio === "NETFLIX");
const flujoItems = todos.filter(item => item.json.tipo_servicio === "FLUJOTV");

// Función flexible para contar perfiles y cuentas completas
function contarInventario(items) {
    // Cuenta como completa si es igual a "CUENTA COMPLETA"
    const completas = items.filter(i => i.json.PERFIL === "CUENTA COMPLETA").length;

    // Cuenta como perfil si contiene la palabra "PERFIL" 
    // Esto detecta tanto "1 PERFIL (1)" como "1 PERFIL" a secas
    const perfiles = items.filter(i => i.json.PERFIL && i.json.PERFIL.includes("PERFIL") && i.json.PERFIL !== "CUENTA COMPLETA").length;

    return { completas, perfiles, total: items.length };
}

const n = contarInventario(netflixItems);
const f = contarInventario(flujoItems);

// Armamos el mensaje detallado
let mensaje = "📊 *ESTADO DEL INVENTARIO* 📊\n\n";

// Sección Netflix
mensaje += "🍿 *Netflix*:\n";
mensaje += (n.total > 0) ? `   - Disponibles: ${n.total}\n   - Completas: ${n.completas}\n   - Perfiles: ${n.perfiles}\n\n` : "   *Sin stock*\n\n";

// Sección Flujo
mensaje += "🌟 *FlujoTV*:\n";
mensaje += (f.total > 0) ? `   - Disponibles: ${f.total}\n   - Completas: ${f.completas}\n   - Perfiles: ${f.perfiles}\n` : "   *Sin stock*\n";

return [{
    json: {
        mensaje_final: mensaje
    }
}];

// Obtenemos los datos del paso anterior
const cuenta = items[0].json;


// ======================================================
// FUNCIONES WHATSAPP
// ======================================================

function encodeUrlSeguro(texto) {
  return encodeURIComponent(texto).replace(/[!'()*]/g, function (c) {
    return "%" + c.charCodeAt(0).toString(16).toUpperCase();
  });
}


function normalizarNumeroWhatsapp(numeroRaw) {
  let numero = String(numeroRaw || "").replace(/\D/g, "");

  // Venezuela con 0 inicial:
  // 04141264402 -> 584141264402
  if (
    numero.startsWith("0") &&
    numero.length === 11
  ) {
    numero = "58" + numero.slice(1);
  }

  // Venezuela sin 58:
  // 4141264402 -> 584141264402
  else if (
    numero.length === 10 &&
    (
      numero.startsWith("412") ||
      numero.startsWith("414") ||
      numero.startsWith("416") ||
      numero.startsWith("422") ||
      numero.startsWith("424") ||
      numero.startsWith("426")
    )
  ) {
    numero = "58" + numero;
  }

  return numero;
}


// ======================================================
// FECHA DE VENCIMIENTO
// ======================================================

// Extraemos el día usando el nombre exacto:
// FECHA QUE ACABA

const fechaVencimiento =
  String(
    cuenta['FECHA QUE ACABA'] || "XX-XX-XX"
  );

const diaVence =
  fechaVencimiento.split('-')[2] || "XX";


// ======================================================
// TIPO DE PERFIL
// ======================================================

const tipoPerfil =
  String(
    cuenta.PERFIL || ""
  )
    .toUpperCase();


// ======================================================
// CONSTRUIR MENSAJE DE ENTREGA
// ======================================================

let mensajeFinal = "";


// ======================================================
// CUENTA COMPLETA
// ======================================================

if (
  tipoPerfil.includes("COMPLETA")
) {

  mensajeFinal = `*⚠️--LEER DETENIDAMENTE TODO--⚠️*
*Datos de Ingreso - Flujo TV*
*Usuario:* ${cuenta.CORREO || cuenta.correo || 'No especificado'}
*Contraseña:* ${cuenta.CONTRASEÑA || cuenta.contrasena || 'No especificada'}

Vence todos los *${diaVence} de cada Mes.*

*Con estos datos de ingreso puede acceder hasta en 3 dispositivos diferentes como máximo, para disfrutar de todo el contenido de manera simultánea*

⚠️ *Si no cumple con estas indicaciones será expulsado de su cuenta sin derecho a reembolso.* ⚠️ 

*🚨Atención!!* le recomendamos que *nos guarde en su lista de contactos y nos recomiende con amigos y familiares* para obtener *descuentos exclusivos*, y podrá ver nuestros estados de WhatsApp y enterarse de las *últimas novedades y promociones.*`;
}


// ======================================================
// PERFIL / 1 DISPOSITIVO
// ======================================================

else {

  mensajeFinal = `*⚠️--LEER DETENIDAMENTE TODO--⚠️*
*Datos de Ingreso - Flujo TV*
*Usuario:* ${cuenta.CORREO || cuenta.correo || 'No especificado'}
*Contraseña:* ${cuenta.CONTRASEÑA || cuenta.contrasena || 'No especificada'}

Vence todos los *${diaVence} de cada Mes.*

Con estos datos de ingreso puede *acceder* hasta en *1 dispositivo* como máximo, para disfrutar de todo el contenido.

⚠️ *Si no cumple con estas indicaciones será expulsado de su cuenta sin derecho a reembolso.* ⚠️ 

*🚨Atención!!* le recomendamos que *nos guarde en su lista de contactos y nos recomiende con amigos y familiares* para obtener *descuentos exclusivos*, y podrá ver nuestros estados de WhatsApp y enterarse de las *últimas novedades y promociones.*`;
}


// ======================================================
// NÚMERO DEL CLIENTE
// ======================================================

const numeroRaw =
  cuenta.NUMERO ||
  cuenta.numero ||
  "";

const numeroOriginal =
  String(numeroRaw)
    .replace(/\D/g, "");

const numeroWhatsapp =
  normalizarNumeroWhatsapp(
    numeroRaw
  );


// ======================================================
// LINK WHATSAPP
//
// IMPORTANTE:
// El mensaje dentro de WhatsApp es SOLO mensajeFinal.
// No incluye el link de Telegram.
// ======================================================

const mensajeCodificado =
  encodeUrlSeguro(
    mensajeFinal
  );

const linkWhatsapp =
  `https://wa.me/${numeroWhatsapp}?text=${mensajeCodificado}`;

const linkWhatsappTelegram =
  `[${numeroWhatsapp}](${linkWhatsapp})`;


// ======================================================
// MENSAJE PARA TELEGRAM
//
// Aquí sí agregamos abajo el número clickeable.
// ======================================================

const mensajeTelegram =
  `${mensajeFinal}

📲 *WhatsApp Cliente:* ${linkWhatsappTelegram}`;


// ======================================================
// RETORNO
// ======================================================

return [
  {
    json: {

      ...cuenta,

      mensajeParaCliente:
        mensajeFinal,

      mensajeParaWhatsapp:
        mensajeFinal,

      numeroOriginal,

      numeroWhatsapp,

      linkWhatsapp,

      linkWhatsappTelegram,

      mensajeTelegram
    }
  }
];

// 1. Obtenemos la clasificación del nodo AI Agent
let etiquetaIA = "";
try {
    etiquetaIA = $('AI Agent').first().json.output || "";
} catch (e) {
    etiquetaIA = "";
}

// 2. Obtenemos el texto del usuario
let mensajeUsuario = "";
try {
    mensajeUsuario = $('Telegram Trigger').first().json.message.text.toLowerCase();
} catch (e) {
    mensajeUsuario = "";
}

let etiquetaFinal = "";

// --- LOGICA DE PRIORIDAD ---

// 1. Si el usuario pide un reporte, prioridad absoluta
if (mensajeUsuario.includes('reporte') || mensajeUsuario.includes('ventas del dia') || mensajeUsuario.includes('cuanto llevo')) {
    etiquetaFinal = 'REPORTE_VENTAS';
}
// 2. Si es una VENTA detectada por la IA
else if (etiquetaIA === 'VENTA_DATOS_CLIENTE_NETFLIX' || etiquetaIA === 'VENTA_DATOS_CLIENTE_FLUJO') {
    etiquetaFinal = etiquetaIA;
}
// 3. NUEVA: Búsqueda de datos de clientes existentes
else if (mensajeUsuario.includes('buscar') || mensajeUsuario.includes('datos de') || mensajeUsuario.includes('info de') || mensajeUsuario.includes('informacion de')) {
    etiquetaFinal = 'BUSCAR_DATOS';
}
// 4. Bloqueos de seguridad
else if (mensajeUsuario.includes('system prompt') || mensajeUsuario.includes('instrucciones') || mensajeUsuario.includes('olvida tus')) {
    etiquetaFinal = 'BLOQUEO_SEGURIDAD';
}
// 5. Precios
else if (mensajeUsuario.includes('precio') || mensajeUsuario.includes('cuanto cuesta') || mensajeUsuario.includes('tasa')) {
    etiquetaFinal = 'PRECIOS';
}
// 6. Disponibilidad
else if (mensajeUsuario.includes('disponibilidad') || mensajeUsuario.includes('stock')) {
    etiquetaFinal = 'DISPONIBILIDAD';
}
// 7. Ayuda general
else if (mensajeUsuario.includes('ayuda') || mensajeUsuario.includes('hola') || mensajeUsuario.includes('info')) {
    etiquetaFinal = 'AYUDA_GENERAL';
}
// 8. Si no es nada de lo anterior, usamos lo que dijo la IA
else {
    etiquetaFinal = etiquetaIA || 'CONSULTA_SERVICIO';
}

// Asignamos la etiqueta final
items[0].json.output = etiquetaFinal;
return items;

// 1. Configuración de fechas
const hoy = new Date();
hoy.setHours(0, 0, 0, 0);
const formatDate = (d) => `${String(d.getDate()).padStart(2, '0')}/${String(d.getMonth() + 1).padStart(2, '0')}/${d.getFullYear()}`;

// 2. Contadores (Cambiado: agrupamos por vendedor)
const r = {
    diario: {}, // { "EDWARD": { netflix: {p:0, c:0}, flujotv: {p:0, c:0} } }
    semanal: { netflix: { perfiles: 0, completas: 0 }, flujotv: { perfiles: 0, completas: 0 } },
    mensual: { netflix: { perfiles: 0, completas: 0 }, flujotv: { perfiles: 0, completas: 0 } }
};

// 3. Procesar datos
items.forEach(i => {
    const d = i.json;
    const fecha = parseFecha(d["FECHA DE INICIO"]);
    const origen = (d.ORIGEN || "").toUpperCase().trim();
    const perfilRaw = (d["PERFIL"] || "").toUpperCase();
    const vendedor = (d["ACOTACION"] || "Sin asignar").trim();

    if (!fecha || !origen) return;
    const esCompleta = perfilRaw.includes("COMPLETA");
    const esPerfil = perfilRaw.includes("PERFIL");
    if (!esCompleta && !esPerfil) return;

    const servicio = origen.includes("NETFLIX") ? "netflix" : "flujotv";

    // DIARIO: Agrupado por vendedor
    if (fecha.toDateString() === hoy.toDateString()) {
        if (!r.diario[vendedor]) r.diario[vendedor] = { netflix: { perfiles: 0, completas: 0 }, flujotv: { perfiles: 0, completas: 0 } };
        esCompleta ? r.diario[vendedor][servicio].completas++ : r.diario[vendedor][servicio].perfiles++;
    }

    // SEMANAL Y MENSUAL (Lógica original)
    if (fecha >= getInicioSemana(hoy) && fecha <= hoy) {
        esCompleta ? r.semanal[servicio].completas++ : r.semanal[servicio].perfiles++;
    }
    if (fecha >= new Date(hoy.getFullYear(), hoy.getMonth(), 1) && fecha <= hoy) {
        esCompleta ? r.mensual[servicio].completas++ : r.mensual[servicio].perfiles++;
    }
});

// 4. Armar reporte
let m = `📊 *REPORTE DE VENTAS AL ${formatDate(hoy)}* 📊\n\n📊 *DIARIA (Por Vendedor)* 📊\n`;

if (Object.keys(r.diario).length === 0) {
    m += "Sin ventas hoy\n";
} else {
    Object.entries(r.diario).forEach(([vendedor, datos]) => {
        m += `\n👤 *${vendedor.toUpperCase()}*:\n`;
        m += `   • Netflix: ${datos.netflix.perfiles} Perfiles, ${datos.netflix.completas} Completas\n`;
        m += `   • Flujo: ${datos.flujotv.perfiles} Perfiles, ${datos.flujotv.completas} Completas\n`;
    });
}

m += `\n📊 *SEMANAL (Desde ${formatDate(getInicioSemana(hoy))})* 📊\n` +
     `NETFLIX: ${r.semanal.netflix.perfiles} Perfiles, ${r.semanal.netflix.completas} Completas\n` +
     `FLUJO TV: ${r.semanal.flujotv.perfiles} Perfiles, ${r.semanal.flujotv.completas} Completas\n\n` +
     `📊 *MENSUAL (Desde ${formatDate(new Date(hoy.getFullYear(), hoy.getMonth(), 1))})* 📊\n` +
     `NETFLIX: ${r.mensual.netflix.perfiles} Perfiles, ${r.mensual.netflix.completas} Completas\n` +
     `FLUJO TV: ${r.mensual.flujotv.perfiles} Perfiles, ${r.mensual.flujotv.completas} Completas`;

return [{ json: { mensaje_final: m } }];

// Funciones auxiliares necesarias
function parseFecha(f) {
    if (!f) return null;
    if (typeof f === 'number') return new Date((f - 25569) * 86400 * 1000);
    const [d, m, y] = f.split('/');
    return new Date(y, m - 1, d);
}
function getInicioSemana(d) {
    let date = new Date(d);
    date.setDate(date.getDate() - date.getDay());
    date.setHours(0, 0, 0, 0);
    return date;
}

// 1. Obtener todas las filas y el mensaje
const todasLasFilas = items; 
const mensaje = $('Telegram Trigger').item.json.message.text.toLowerCase();

// NUEVO: Detectar cancelación antes de validar tipo de cuenta
const esCancelar =
    mensaje.includes("cancelar") ||
    mensaje.includes("cacelar");

if (esCancelar) {
    throw new Error("CANCELAR");
}

// 2. Definir palabras clave estrictas
const pidePerfil = mensaje.includes("perfil");
const pideCompleta = mensaje.includes("completa");

// 3. Validación de seguridad: Si no hay ninguna palabra clave, lanzamos error inmediato
if (!pidePerfil && !pideCompleta) {
    throw new Error("TIPO_DE_CUENTA_NO_ESPECIFICADO");
}

// 4. Filtrar filas
const filasDisponibles = todasLasFilas.filter(item => {
    const fila = item.json;

    const estado = (fila['ESTADO D'] || "").toString().trim();
    const perfilRaw = (fila['PERFIL'] || "").toString().trim();

    const esDisponible = estado === 'DISPONIBLE';

    let coincideTipo = false;
    if (pidePerfil) {
        // Busca si el perfil contiene '1 PERFIL'
        coincideTipo = perfilRaw.includes('1 PERFIL');
    } else if (pideCompleta) {
        // Busca si el perfil contiene 'CUENTA COMPLETA'
        coincideTipo = perfilRaw.includes('CUENTA COMPLETA');
    }

    return esDisponible && coincideTipo;
});

// 5. Resultado
if (filasDisponibles.length > 0) {
    return { etiqueta: pidePerfil ? "HAY_PERFILES" : "HAY_COMPLETAS" };
} else {
    // Si no encuentra nada disponible, pero el usuario sí especificó el tipo
    throw new Error(pidePerfil ? "NO_HAY_PERFILES" : "NO_HAY_COMPLETAS");
}

// 1. Obtener todas las filas
const todasLasFilas = items; 
const mensaje = $('Telegram Trigger').item.json.message.text.toLowerCase();

// NUEVO: Detectar cancelación antes de validar tipo de cuenta
const esCancelar =
    mensaje.includes("cancelar") ||
    mensaje.includes("cacelar");

if (esCancelar) {
    throw new Error("CANCELAR");
}

const buscandoPerfil = mensaje.includes("perfil");
const buscandoCompleta = mensaje.includes("completa");

// 2. Si no pide tipo, MANDAMOS ERROR para que se vaya por la salida de ABAJO (Error)
if (!buscandoPerfil && !buscandoCompleta) {
    throw new Error("ESPECIFICAR_TIPO");
}

// 3. Filtrar
const filasDisponibles = todasLasFilas.filter(item => {
    const fila = item.json;
    const estado = (fila['ESTADO D'] || "").toString().trim();
    const perfil = (fila['PERFIL'] || "").toString().toUpperCase();
    return estado === 'DISPONIBLE' && 
           (buscandoPerfil ? perfil.includes('PERFIL') : perfil.includes('CUENTA COMPLETA'));
});

// 4. Si hay cuentas, mandamos a ARRIBA (Success)
if (filasDisponibles.length > 0) {
    return [{ json: { etiqueta: buscandoPerfil ? "HAY_PERFILES" : "HAY_COMPLETAS" } }];
} else {
    // Si NO hay cuentas, MANDAMOS ERROR para que se vaya por la salida de ABAJO (Error)
    throw new Error(buscandoPerfil ? "NO_HAY_PERFILES" : "NO_HAY_COMPLETAS");
}

