// 1. Obtenemos el objeto que nos envió la IA
// Limpiamos los bloques de código ```json y ``` por si acaso
let rawData = items[0].json.output; 
if (typeof rawData === 'string') {
    rawData = JSON.parse(rawData.replace(/```json|```/g, '').trim());
}

// 2. ¿El usuario quiere cancelar?
if (rawData.cancelar === "true" || rawData.cancelar === true) {
    throw new Error("CANCELAR_COMPRA");
}

// 3. Mapeo de datos (La IA envía, nosotros validamos)
const datos = {
    nombre: rawData.nombre_apellido || "No encontrado",
    monto: rawData.monto || "No encontrado",
    estado_pais: rawData.estado_pais || "No encontrado",
    telefono: rawData.telefono || "No encontrado",
    chat_id: rawData.chat_id || "No encontrado",
    correo: rawData.correo || "No encontrado",
    contrasena: rawData.contraseña || "No encontrado",
    perfil: rawData.perfil || "No encontrado",
    meses: rawData["meses que pago"] || "No encontrado",
    row_number: rawData.row_number || "No encontrado" // <--- Aquí validamos la etiqueta nueva
};

// 4. Validación de campos obligatorios
// Agregamos 'row_number' a la lista de chequeo
const camposObligatorios = [
    'nombre', 'monto', 'estado_pais', 'telefono', 'chat_id', 
