// Recibimos el texto, que ahora viene separado por saltos de línea (\n)
const input = items[0].json.output.trim();

// Si el bot responde 'ERROR' (o cualquier cosa que no tenga el formato), salimos
if (input === 'ERROR' || !input.includes('|')) {
    return { json: { error: true, mensaje: 'No se entendió la selección' } };
}

// Dividimos por saltos de línea
const filas = input.split('\n');

// Mapeamos cada fila
return filas.map(fila => {
    // Ajustado al orden: numero, servicio, correo, perfil, nombre
    const [numero, servicio, correo, perfil, nombre] = fila.split('|');

    return { 
        json: { 
            seleccion: numero.trim(),
            servicio: servicio.trim(),      // Ahora es el segundo dato
            correoBuscado: correo.trim(),   // Ahora es el tercer dato
            perfil: perfil.trim(),
            nombre: nombre.trim()
        } 
    };
});

// Obtenemos los ítems que vienen del Merge3
const items = $input.all();

// Filtramos solo los que tengan un CORREO o NUMERO (dato real)
const datosValidos = items.filter(item => item.json.CORREO || item.json.NUMERO);

if (datosValidos.length > 0) {
    // Si hay al menos un dato (de Netflix, de Flujo o de ambos), pasamos los datos
    return datosValidos;
} else {
    // Si no hay nada, lanzamos un error para activar tu rama de "Error"
    throw new Error("NO_ENCONTRADO");
}

// Convierte a número de forma segura (acepta "2", "2.0", "2 días", "-10", etc.)
function toNumber(v) {
  const n = parseFloat(String(v).replace(/[^\d.-]/g, ''));
  return Number.isFinite(n) ? n : null;
}

return items.filter(item => {
  const dias = toNumber(item.json['DIAS']);
  // Mantén solo -50 <= dias <= 2
  return dias !== null && dias >= -50 && dias <= 2;
});

/**
 * n8n Code node - Agrupar clientes por pago (5,7,9) y subgrupos por estatus.
 * Salida: { grupo_1: {...}, grupo_2: {...}, grupo_3: {...} }
 * Cada grupo contiene: sub_g_vencido[], sub_g_por_vencer[], sub_g_con_tiempo[]
 */

// --- Helpers ---
// Convierte a número tolerando strings con símbolos/espacios/comas/puntos.
function toNumber(v) {
  if (v === null || v === undefined) return undefined;
  const s = String(v).replace(/[^0-9.+-]/g, '');
  const n = Number(s);
  return Number.isFinite(n) ? n : undefined;
}

// Normaliza el estatus a: 'vencido' | 'por vencer' | 'vigente' | 'otros'
function normalizeStatus(s) {
  if (!s) return 'otros';
  const t = String(s)
    .toLowerCase()
    .normalize('NFD')
    .replace(/\p{Diacritic}/gu, '') // quita acentos
    .trim();

  if (t.includes('vencido')) return 'vencido';
  if (t.includes('por vencer') || t.includes('porvencer')) return 'por vencer';
  if (t.includes('vigente') || t.includes('vigente')) return 'vigente';
  return 'otros';
}

// Mapea pago -> grupo
function getGroupKey(pago) {
  if (pago === 5) return 'grupo_1';
  if (pago === 9) return 'grupo_2';
  if (pago === 4) return 'grupo_3';
  if (pago === 15) return 'grupo_4';
  return null; // otros pagos se ignoran (no solicitado)
}

// Crea la estructura base de subgrupos
const makeGroup = () => ({
  sub_g_vencido: [],
  sub_g_por_vencer: [],
  sub_g_vigente: [],
});

// Estructura resultado
const groups = {
  grupo_1: makeGroup(),
  grupo_2: makeGroup(),
  grupo_3: makeGroup(),
  grupo_4: makeGroup(),
};

// Procesa todos los items de entrada
for (const item of $input.all()) {
  const j = item.json || {};

  // Lee y normaliza pago/estatus desde distintas posibles claves
  const pago = toNumber(j.pago ?? j['PAGO']);
  const estatus = normalizeStatus(j.estatus ?? j['ESTATUS']);

  // Identifica grupo por pago (solo 5,9,4,15)
  const groupKey = getGroupKey(pago);
  if (!groupKey) continue; // si no es 5/9/4/15, lo ignoramos

  // Selecciona el subgrupo por estatus
  const group = groups[groupKey];
  const clean = {
    // Campos útiles (ajusta a tu esquema real)
    nombre_cliente: j.nombre_cliente ?? j['NOMBRE CLIENTE'] ?? j.name ?? null,
    cuenta_cliente: j.cuenta_cliente ?? j['CUENTA CLIENTE'] ?? null,
    dias_restantes: toNumber(j.dias_restantes ?? j['DIAS RESTANTES']),
    estatus, // ya normalizado
    numeros: j.numeros ?? j['NUMEROS'] ?? null,
    pago,    // ya en number
    row_number: j.row_number ?? j['row_number'] ?? null,
  };

  if (estatus === 'vencido') group.sub_g_vencido.push(clean);
  else if (estatus === 'por vencer') group.sub_g_por_vencer.push(clean);
  else if (estatus === 'vigente') group.sub_g_vigente.push(clean);
  // Si cae en 'otros' no se agrega, porque solo pediste esos 3 subgrupos
}

// Devuelve UN item con la estructura de grupos/subgrupos
return [{ json: groups }];

// --- Utilidad robusta para convertir a Number ---
// - Acepta números en string con símbolos, espacios, comas o puntos.
// - Devuelve undefined si no es convertible.
function toNumber(v) {
  if (v === null || v === undefined) return undefined;
  let s = String(v).trim();
  // Normaliza: quita espacios, deja signos y dígitos, convierte coma decimal a punto
  s = s.replace(/\s+/g, '').replace(/,/g, '.').replace(/[^0-9.+-]/g, '');
  const n = Number(s);
  return Number.isFinite(n) ? n : undefined;
}

// --- Obtiene la fecha del item aceptando varias claves posibles ---
function extractDate(item) {
  const j = item.json || {};
  const raw =
    j["Día"] ?? j["Dia"] ?? j["día"] ?? j["dia"] ??
    j["Fecha"] ?? j["fecha"] ?? null;
  // Si no hay fecha válida, Date("") => Invalid Date
  return new Date(raw || '');
}

// 1) Tomamos todos los items de entrada
const items = $input.all();

// 2) Elegimos el item con la fecha más reciente
let latest = null;
let latestTime = -Infinity;

for (const it of items) {
  const d = extractDate(it);
  const t = d.getTime();
  if (Number.isFinite(t) && t > latestTime) {
    latest = it;
    latestTime = t;
  }
}

// Si no encontramos fecha válida, usamos el primero para no romper el flujo
if (!latest) latest = items[0] ?? { json: {} };

// 3) Convertimos tasas y armamos la salida mínima
const j = latest.json || {};
const out = {
  tasa5: toNumber(j["Tasa 5$"]),
  tasa7: toNumber(j["Tasa 7$"]),
  tasa9: toNumber(j["Tasa 9$"]),
  tasa4: toNumber(j["Tasa 4$"]),
  tasa15: toNumber(j["Tasa 15$"]),
};

// 4) Devolvemos un solo item con las tasas en Number
return [{ json: out }];

/**
 * Resumen por grupos (Vencidos -> Por vencer 1 día -> Por vencer 2 días)
 * - Corta por grupo; si un grupo excede el límite, se parte dentro del grupo.
 * - Límite recomendado: MAX_PER_MSG = 3800 (Telegram máx 4096).
 * - Estatus: "con tiempo" => "por vencer en 2 dias"; "vencido" => "vencida".
 * - Número clicable con <a href="...">NUMERO</a> (usar Parse Mode = HTML en Telegram).
 */

// ===== Ajuste de partición =====
const MAX_PER_MSG = 3950; // puedes subir a 4000, pero deja colchón

// ===== Utilidades =====
function toNumber(v) {
  if (v === null || v === undefined) return undefined;
  const s = String(v).replace(/,/g, '.').replace(/[^0-9.+-]/g, '');
  const n = Number(s);
  return Number.isFinite(n) ? n : undefined;
}

function normalizeStatus(s) {
  if (!s) return 'otros';
  const t = String(s)
    .toLowerCase()
    .normalize('NFD')
    .replace(/[\u0300-\u036f]/g, '') // quita acentos (compatible)
    .trim();
  if (t.includes('vencido')) return 'vencido';
  if (t.includes('por vencer') || t.includes('porvencer')) return 'por vencer';
  if (t.includes('vigente') || t.includes('vigente')) return 'vigente';
  return 'otros';
}

// Estatus para mostrar en mensajes de WhatsApp
function displayStatus(norm) {
  if (norm === 'vencido') return 'vencida';
  if (norm === 'por vencer') return 'por vencer mañana';
  if (norm === 'vigente') return 'por vencer en 2 dias';
  return norm; // 'por vencer' u otros
}

// Teléfono → E.164 dígitos (por defecto +58)
function extractPhone(raw, defaultCountry = '58') {
  if (!raw) return null;
  const all = String(raw).match(/\+?\d{7,15}/g) || [];
  if (!all.length) return null;
  let ph = all[0].replace(/[()\s.-]/g, '');
  if (ph.startsWith('+')) ph = ph.slice(1);
  if (/^0\d{10}$/.test(ph)) ph = defaultCountry + ph.slice(1); // VE: 0XXXXXXXXXX
  if (/^\d{10}$/.test(ph))  ph = defaultCountry + ph;          // VE: 10 dígitos
  return /^\d{9,15}$/.test(ph) ? ph : null;
}

// Mensaje ÚNICO de WhatsApp para todos los estados (Dinámico por Monto)
function buildMessage(client, tasas) {
  const cuenta  = client.cuenta_cliente ?? '';
  const estatus = displayStatus(client.estatus ?? '');

  // Detecta el monto real del cliente (si no tiene, usa 4 por defecto)
  const montoUsd = client.pago || 4; 
  // Busca la tasa correspondiente (tasa4, tasa15, etc.)
  const tasaClave = `tasa${montoUsd}`;
  const montoBs = tasas[tasaClave] || 0;

  const msg = `**Hola,** **👋, tu cuenta** ${cuenta}.

Y acceso a **FLUJOTV** esta **${estatus}**.

💵 Monto de renovación: **$${montoUsd} | ${montoBs} Bs**

⚠️ No dejes que tu entretenimiento se corte: ¡asegura tu renovación hoy mismo!

➡️ Mientras más meses asegures, **menos pagas por mes** y además te proteges de futuros aumentos del dólar.

---

📌 Métodos de pago (tasa promedio):

*PAGO MÓVIL1:*
*Cedula*: V29.780.686
*Telefono*: 04141264402
*Bancos*: *Banesco*

*PAGO MÓVIL2:*
*Cedula*: V25.964.140
*Telefono*: 04241815827
*Bancos*: *Venezuela* 

Hacerlo al banco de su preferencia.
---

💰 También aceptamos: **Zelle** y **Binance** (consultar antes de pagar).`;

  // Limpieza: convertir **negritas** (Markdown) a *negritas* (WhatsApp)
  return msg.replace(/\*\*/g, '*');
}

// Link wa.me con texto codificado
function waLink(phoneDigits, messageText) {
  const encoded = encodeURIComponent(messageText);
  return `https://wa.me/${phoneDigits}?text=${encoded}`;
}

// Escapa HTML (Telegram Parse Mode = HTML)
function escapeHtml(s) {
  return String(s ?? '')
    .replace(/&/g, '&amp;')
    .replace(/</g, '&lt;')
    .replace(/>/g, '&gt;')
    .replace(/"/g, '&quot;');
}

// Aplana grupos con o sin subgrupos
function flattenFromGroups(obj) {
  const out = [];
  const tryPush = (arr) => Array.isArray(arr) && arr.forEach(v => v && out.push(v));
  ['grupo_1', 'grupo_2', 'grupo_3'].forEach(k => {
    const g = obj[k];
    if (!g) return;
    if (g.sub_g_vencido || g.sub_g_por_vencer || g.sub_g_vigente) {
      tryPush(g.sub_g_vencido);
      tryPush(g.sub_g_por_vencer);
      tryPush(g.sub_g_vigente);
    } else if (Array.isArray(g)) {
      tryPush(g);
    }
  });
  return out;
}

// Partir texto largo en trozos ≤ max (preferir cortes en saltos)
function chunk(text, max) {
  if (max == null || text.length <= max) return [text]; // sin corte
  const out = [];
  let i = 0;
  while (i < text.length) {
    let end = Math.min(i + max, text.length);
    if (end < text.length) {
      // intenta cortar en doble salto; si no, en un salto
      let cut = text.lastIndexOf('\n\n', end);
      if (cut <= i + 200) cut = text.lastIndexOf('\n', end);
      if (cut > i) end = cut;
    }
    out.push(text.slice(i, end));
    i = end;
  }
  return out;
}

// ===== Recolección de datos de entrada =====
const inputs = $input.all();
// Se añade tasa15 a la lista de tasas aceptadas
const tasas = { tasa4: undefined, tasa5: undefined, tasa7: undefined, tasa9: undefined, tasa15: undefined };
const allClients = [];

// Extrae tasas y/o clientes desde los items del input
for (const it of inputs) {
  const j = it.json || {};
  if (j.tasa4 !== undefined || j.tasa5 !== undefined || j.tasa7 !== undefined || j.tasa9 !== undefined || j.tasa15 !== undefined) {
    tasas.tasa4 = toNumber(j.tasa4);
    tasas.tasa5 = toNumber(j.tasa5);
    tasas.tasa7 = toNumber(j.tasa7);
    tasas.tasa9 = toNumber(j.tasa9);
    tasas.tasa15 = toNumber(j.tasa15); // Captura la tasa 15 si viene en el input
    continue;
  }
  if (j.grupo_1 || j.grupo_2 || j.grupo_3) {
    allClients.push(...flattenFromGroups(j));
    continue;
  }
  if (j.pago !== undefined || j['PAGO'] !== undefined) {
    allClients.push(j);
  }
}

// Clasificación de clientes a notificar
const vencidos = [], porVencer = [], con2dias = [];
for (const c of allClients) {
  const cliente = {
    nombre_cliente : c.nombre_cliente ?? c['NOMBRE CLIENTE'] ?? c.name ?? '',
    cuenta_cliente : c.cuenta_cliente ?? c['CUENTA CLIENTE'] ?? '',
    dias_restantes : toNumber(c.dias_restantes ?? c['DIAS RESTANTES']),
    estatus        : normalizeStatus(c.estatus ?? c['ESTATUS']),
    pago           : toNumber(c.pago ?? c['PAGO']),
    numeros        : c.numeros ?? c['NUMEROS'] ?? c.telefono ?? c['TELEFONO'] ?? '',
  };

  if (cliente.estatus === 'vencido' && Number.isFinite(cliente.dias_restantes)
      && cliente.dias_restantes <= 0 && cliente.dias_restantes >= -50) {
    vencidos.push(cliente);
  } else if (cliente.estatus === 'por vencer' && cliente.dias_restantes === 1) {
    porVencer.push(cliente);
  } else if (cliente.estatus === 'vigente' && cliente.dias_restantes === 2) {
    con2dias.push(cliente);
  }
}

// Orden interno
vencidos.sort((a,b)=>a.dias_restantes - b.dias_restantes);
porVencer.sort((a,b)=>a.dias_restantes - b.dias_restantes);
con2dias.sort((a,b)=>a.dias_restantes - b.dias_restantes);

// Línea por cliente (número clicable con link oculto)
function renderClienteLinea(cli) {
  const phoneDigits = extractPhone(cli.numeros, '58');
  const msg  = buildMessage(cli, tasas);
  const link = phoneDigits ? waLink(phoneDigits, msg) : null;

  const nombre = escapeHtml(cli.nombre_cliente || 'N/A');
  const cuenta = escapeHtml(cli.cuenta_cliente || 'N/A');
  const dias   = escapeHtml(cli.dias_restantes ?? 'N/A');
  const numVis = escapeHtml(cli.numeros || phoneDigits || 'N/A');

  return [
    `🧍‍♂️ Nombre: ${nombre}`,
    `🆔 Cuenta: ${cuenta}`,
    `📅 Días restantes: ${dias}`,
    link ? `📞 WhatsApp: <a href="${link}">${numVis}</a>` : `📞 Número: ${numVis}`
  ].join('\n');
}

// Render de cada bloque (grupo)
function buildBlock(title, arr) {
  if (!arr.length) return null;
  const lines = [`${title} — ${arr.length}`, ''];
  arr.forEach(c => { lines.push(renderClienteLinea(c), ''); });
  return lines.join('\n');
}

// Construir bloques por grupo (en este orden)
const blocks = [];
const header = '📢 *ESTADO DE CLIENTES FLUJOTV*\n';

const b1 = buildBlock('🟥 *Clientes Vencidos* (0 a -50 días)', vencidos);
if (b1) blocks.push(b1);

const b2 = buildBlock('🟨 Clientes por vencer (1 día)', porVencer);
if (b2) blocks.push(b2);

const b3 = buildBlock('🟦 Clientes por vencer (2 días)', con2dias);
if (b3) blocks.push(b3);

// ====================================================================
// 🔥 CORRECCIÓN AQUÍ: Forzamos a que el título "FLUJOTV" aparezca SIEMPRE 
// en el primer mensaje de la lista, no importa cuál subgrupo tenga datos.
// ====================================================================
if (blocks.length > 0) {
  blocks[0] = header + blocks[0];
}

// Salida: 1..N items (uno por bloque, y si un bloque > MAX_PER_MSG, se parte)
const out = [];
for (const blk of blocks) {
  const parts = chunk(blk, MAX_PER_MSG);
  if (parts.length === 1) {
    out.push({ json: { text: parts[0] } });
  } else {
    parts.forEach((p, i) => {
      out.push({ json: { text: `${p}\n\n(Parte ${i+1}/${parts.length})` } });
    });
  }
}
// Agregar los datos del resumen al output
out.push({
  json: {
    es_resumen: true,
    servicio: 'FLUJOTV',
    vencidos: vencidos.length,
    p1: porVencer.length,
    p2: con2dias.length,
    total: vencidos.length + porVencer.length + con2dias.length
  }
});
return out;

