const inputs = $input.all();

let netflixTexts = [];
let flujoTexts = [];

// Valores por defecto en 0 para evitar undefined
let nfx = { vencidos: 0, p1: 0, p2: 0, total: 0 };
let flujo = { vencidos: 0, p1: 0, p2: 0, total: 0 };

// 1. Extraer y clasificar la información
for (const item of inputs) {
  const j = item.json;

  if (j.es_resumen) {
    // Si es la etiqueta de resumen, guardamos los números exactos
    if (j.servicio === 'NETFLIX') {
      nfx = {
        vencidos: j.vencidos || 0,
        p1: j.p1 || 0,
        p2: j.p2 || 0,
        total: j.total || 0
      };
    } else if (j.servicio === 'FLUJOTV') {
      flujo = {
        vencidos: j.vencidos || 0,
        p1: j.p1 || 0,
        p2: j.p2 || 0,
        total: j.total || 0
      };
    }
  } else if (j.text) {
    // Si es un bloque de texto, lo asignamos a su servicio
    if (j.text.includes('NETFLIX')) {
      netflixTexts.push(j.text);
    } else if (j.text.includes('FLUJOTV')) {
      flujoTexts.push(j.text);
    }
  }
}

// 2. Construir la estructura principal
let textoCompleto = '';

if (netflixTexts.length > 0) {
  textoCompleto += netflixTexts.join('\n\n') + '\n\n-----------\n\n';
}

if (flujoTexts.length > 0) {
  textoCompleto += flujoTexts.join('\n\n') + '\n\n-----------\n\n';
}

// 3. Crear el bloque final de resumen
const resumenBlock = `📊 *RESUMEN DE VENCIMIENTOS:* 📊

*NETFLIX*
🟥 - Vencidos: ${nfx.vencidos}
🟨 • Por vencer (1 día): ${nfx.p1}
🟦 • Por vencer (2 días): ${nfx.p2}
📊 • Total: ${nfx.total}

*FLUJOTV*
🟥 - Vencidos: ${flujo.vencidos}
🟨 • Por vencer (1 día): ${flujo.p1}
🟦 • Por vencer (2 días): ${flujo.p2}
📊 • Total: ${flujo.total}`;

// Unir todo el texto
textoCompleto += resumenBlock;

// 4. Función para dividir textos muy largos (límite de Telegram)
function chunkText(text, max = 3900) {
  if (text.length <= max) return [text];
  const out = [];
  let i = 0;
  while (i < text.length) {
    let end = Math.min(i + max, text.length);
    if (end < text.length) {
      // Intentar cortar en un doble salto de línea para no romper un cliente
      let cut = text.lastIndexOf('\n\n', end);
      if (cut <= i + 100) cut = text.lastIndexOf('\n', end);
      if (cut <= i) cut = end; // Seguridad en caso de bucle infinito
      end = cut;
    }
    out.push(text.slice(i, end).trim());
    i = end;
  }
  return out;
}

// 5. Generar la salida final
const parts = chunkText(textoCompleto, 3900);
const finalOut = [];

if (parts.length === 1) {
  finalOut.push({ json: { text: parts[0] } });
} else {
  parts.forEach((p, index) => {
    finalOut.push({ json: { text: `${p}\n\n*(Parte ${index + 1} de ${parts.length})*` } });
  });
}

return finalOut;

