// Tomar todos los items que entrega el Merge
const items = $input.all();

// Función para codificar bien el texto dentro del link
function encodeUrlSeguro(texto) {
  return encodeURIComponent(texto).replace(/[!'()*]/g, function (c) {
    return "%" + c.charCodeAt(0).toString(16).toUpperCase();
  });
}

// Función para limpiar perfil Netflix
function limpiarPerfilNetflix(perfil) {
  const texto = String(perfil || "").trim();
  const textoMayus = texto.toUpperCase();

  if (textoMayus.includes("CUENTA COMPLETA")) {
    return "Cuenta completa";
  }

  if (textoMayus.includes("PERFIL EXTRA")) {
    return "1";
  }

  const matches = [...texto.matchAll(/\((\d+)\)/g)].map(m => m[1]);

  if (matches.length > 0) {
    const unicos = [...new Set(matches)];

    if (unicos.length === 1) {
      return unicos[0];
    }

    if (unicos.length === 2) {
      return `${unicos[0]} y ${unicos[1]}`;
    }

    return `${unicos.slice(0, -1).join(", ")} y ${unicos[unicos.length - 1]}`;
  }

  const limpio = texto
    .replace(/\b\d+\s*PERFIL(?:ES)?\b/gi, "")
    .replace(/\bPERFIL(?:ES)?\b/gi, "")
    .replace(/[()]/g, "")
    .replace(/\s+/g, " ")
    .trim();

  return limpio || texto;
}

// Función para normalizar número WhatsApp
function normalizarNumero(numeroRaw) {
  let numeroOriginal = String(numeroRaw || "").replace(/\D/g, "");
  let numeroWhatsapp = numeroOriginal;

  if (numeroWhatsapp.startsWith("0") && numeroWhatsapp.length === 11) {
    numeroWhatsapp = "58" + numeroWhatsapp.slice(1);
  }

  else if (
    numeroWhatsapp.length === 10 &&
    (
      numeroWhatsapp.startsWith("412") ||
      numeroWhatsapp.startsWith("414") ||
      numeroWhatsapp.startsWith("416") ||
      numeroWhatsapp.startsWith("422") ||
      numeroWhatsapp.startsWith("424") ||
      numeroWhatsapp.startsWith("426")
    )
  ) {
    numeroWhatsapp = "58" + numeroWhatsapp;
  }

  return {
    numeroOriginal,
    numeroWhatsapp,
  };
}

// Leer salida de AI Agent4
function obtenerTextoAIAgent4() {
  try {
    const aiItems = $("AI Agent4").all();

    return aiItems.map(item => {
      const j = item.json || {};

      return [
        j.output,
        j.text,
        j.response,
        j.message,
        j.ULTIMA_LISTA,
        j.ultima_lista
      ].filter(Boolean).join("\n");
    }).join("\n");
  } catch (e) {
    return "";
  }
}

// Detectar pedido desde AI Agent4
function detectarPedidoDesdeAI4(json, index) {
  const textoAI = obtenerTextoAIAgent4();
  const textoMayus = String(textoAI || "").toUpperCase();

  const correo = String(json["CORREO"] || "").trim().toUpperCase();
  const perfil = String(json["PERFIL"] || "").trim().toUpperCase();

  const lineas = String(textoAI || "")
    .split(/\r?\n/)
    .map(l => l.trim())
    .filter(Boolean);

  const lineaCuenta = lineas.find(linea => {
    const l = linea.toUpperCase();

    const coincideCorreo = correo && l.includes(correo);
    const coincidePerfil = perfil && l.includes(perfil);

    return coincideCorreo || coincidePerfil;
  });

  const textoCuenta = lineaCuenta ? lineaCuenta.toUpperCase() : textoMayus;

  if (
    textoCuenta.includes("PEDIDO:CONTRASEÑA") ||
    textoCuenta.includes("PEDIDO: CONTRASEÑA") ||
    textoCuenta.includes("CAMBIO DE CONTRASEÑA")
  ) {
    return "contraseña";
  }

  if (
    textoCuenta.includes("PEDIDO:ENVIAR DATOS") ||
    textoCuenta.includes("PEDIDO: ENVIAR DATOS") ||
    textoCuenta.includes("ENVIAR DATOS")
  ) {
    return "enviar datos";
  }

  return "enviar datos";
}

// Procesar todos los items
return items.map((item, index) => {
  const json = item.json;

  const correo = json["CORREO"] || "";
  const contrasena = json["CONTRASEÑA"] || "";
  const perfilRaw = json["PERFIL"] || "";
  const fechaVence = json["FECHA QUE ACABA"] || "";
  const numeroRaw = json["NUMERO"] || "";
  const tipoServicioRaw = json["tipo_servicio"] || "";

  if (!numeroRaw) {
    return {
      json: {
        ...json,
        error: true,
        itemIndex: index,
        mensaje: "No se encontró el campo NUMERO.",
        datosRecibidos: json,
      },
    };
  }

  const { numeroOriginal, numeroWhatsapp } = normalizarNumero(numeroRaw);

  const tipoServicio = String(tipoServicioRaw).trim().toUpperCase();

  let servicio = "SERVICIO";

  if (tipoServicio.includes("NETFLIX")) {
    servicio = "NETFLIX";
  } else if (
    tipoServicio.includes("FLUJOTV") ||
    tipoServicio.includes("FLUJO TV") ||
    tipoServicio.includes("FLUJO")
  ) {
    servicio = "FLUJOTV";
  }

  const perfil = servicio === "NETFLIX"
    ? limpiarPerfilNetflix(perfilRaw)
    : String(perfilRaw).trim();

  const pin = servicio === "NETFLIX" ? numeroOriginal.slice(-4) : "";

  const pedido = detectarPedidoDesdeAI4(json, index);

  let mensajeBase = `👤 *Correo:* ${correo}
🔒 *Contraseña:* ${contrasena}
🎞 *Perfil:* ${perfil}`;

  if (servicio === "NETFLIX") {
    mensajeBase += `
🔑 *PIN:* ${pin}`;
  }

  mensajeBase += `
📅 *Vence:* ${fechaVence}`;

  let mensajeParaWhatsapp = "";

  if (pedido === "contraseña") {
    mensajeParaWhatsapp = `*DATOS DE INGRESO - ${servicio}*

no se alarme hubo un cambio de contraseña le enviamos la información para que sepa sus datos de ingreso actuales

${mensajeBase}`;
  } else {
    mensajeParaWhatsapp = `*DATOS DE INGRESO - ${servicio}*

${mensajeBase}`;
  }

  const mensajeCodificado = encodeUrlSeguro(mensajeParaWhatsapp);

  const linkWhatsapp = `https://wa.me/${numeroWhatsapp}?text=${mensajeCodificado}`;

  const linkWhatsappTelegram = `[${numeroWhatsapp}](${linkWhatsapp})`;

  const mensajeTelegram = `${mensajeParaWhatsapp}

📲 *WhatsApp Cliente:* ${linkWhatsappTelegram}`;

  return {
    json: {
      ...json,
      mensajeTelegram,
      mensajeParaWhatsapp,
      numeroOriginal,
      numeroWhatsapp,
      linkWhatsapp,
      linkWhatsappTelegram,
      servicio,
      perfilOriginal: perfilRaw,
      perfilLimpio: perfil,
      pin,
      pedido,
      itemIndex: index,
    },
  };
});

// Recibir texto generado por la IA
const inputText =
  $json.output ||
  $json.text ||
  $json.message ||
  $json.mensaje ||
  $json.respuesta ||
  "";

// Buscar número después de "NUMERO:"
const numeroMatch = inputText.match(/NUMERO\s*:\s*([+\d\s\-().]+)/i);

if (!numeroMatch) {
  return [
    {
      json: {
        error: true,
        mensaje: "No se encontró el NUMERO en el texto recibido.",
        textoOriginal: inputText,
      },
    },
  ];
}

// Limpiar número: solo dígitos
let numeroOriginal = numeroMatch[1].replace(/\D/g, "");

// Normalizar número para WhatsApp
let numeroWhatsapp = numeroOriginal;

// Venezuela con 0 inicial: 04141264402 -> 584141264402
if (numeroWhatsapp.startsWith("0") && numeroWhatsapp.length === 11) {
  numeroWhatsapp = "58" + numeroWhatsapp.slice(1);
}

// Venezuela sin 58: 4141264402 -> 584141264402
else if (
  numeroWhatsapp.length === 10 &&
  (
    numeroWhatsapp.startsWith("412") ||
    numeroWhatsapp.startsWith("414") ||
    numeroWhatsapp.startsWith("416") ||
    numeroWhatsapp.startsWith("424") ||
    numeroWhatsapp.startsWith("426")
  )
) {
  numeroWhatsapp = "58" + numeroWhatsapp;
}

// Si es USA o extranjero y ya viene completo, se deja igual
else {
  numeroWhatsapp = numeroWhatsapp;
}

// Quitar línea NUMERO
let mensajeBase = inputText
  .replace(/NUMERO\s*:\s*[+\d\s\-().]+/i, "")
  .trim();

// Detectar servicio ANTES de limpiar título
let servicio = "SERVICIO";

if (/netflix/i.test(mensajeBase)) {
  servicio = "NETFLIX";
} else if (/flujotv|flujo tv|flujo/i.test(mensajeBase)) {
  servicio = "FLUJOTV";
}

// Detectar aviso de cambio de contraseña
const avisoCambio = "no se alarme hubo un cambio de contraseña le enviamos la información para que sepa sus datos de ingreso actuales";

const tieneAvisoCambio = mensajeBase
  .toLowerCase()
  .includes(avisoCambio.toLowerCase());

// Quitar cualquier título previo para evitar duplicados
mensajeBase = mensajeBase
  .replace(/\*?DATOS DE INGRESO ACTUALIZADOS\s*-\s*(NETFLIX|FLUJOTV|FLUJO TV|SERVICIO)\*?/gi, "")
  .replace(/\*?DATOS DE INGRESO ACTUALIZADOS-\s*(NETFLIX|FLUJOTV|FLUJO TV|SERVICIO)\*?/gi, "")
  .replace(/\*?DATOS DE INGRESO\s*-\s*(NETFLIX|FLUJOTV|FLUJO TV|SERVICIO)\*?/gi, "")
  .replace(/DATOS DE INGRESO\s*-\s*(NETFLIX|FLUJOTV|FLUJO TV|SERVICIO)/gi, "")
  .trim();

// Quitar aviso del cuerpo para luego colocarlo bien separado
mensajeBase = mensajeBase
  .replace(new RegExp(avisoCambio, "i"), "")
  .trim();

// Normalizar etiquetas y formato
mensajeBase = mensajeBase
  // Normalizar etiquetas
  .replace(/👤\s*\*?Correo:\*?/gi, "👤 *Correo:*")
  .replace(/🔒\s*\*?Contraseña:\*?/gi, "🔒 *Contraseña:*")
  .replace(/🎞\s*\*?Perfil:\*?/gi, "🎞 *Perfil:*")
  .replace(/🔑\s*\*?PIN:\*?/gi, "🔑 *PIN:*")
  .replace(/📅\s*\*?Vence:\*?/gi, "📅 *Vence:*")

  // Quitar texto de instrucción si la IA lo deja
  .replace(/\(Si es NETFLIX, agrega:\s*/gi, "")
  .replace(/\)/g, "")

  // Forzar salto de línea antes de cada campo
  .replace(/\s*👤 \*Correo:\*/g, "\n👤 *Correo:*")
  .replace(/\s*🔒 \*Contraseña:\*/g, "\n🔒 *Contraseña:*")
  .replace(/\s*🎞 \*Perfil:\*/g, "\n🎞 *Perfil:*")
  .replace(/\s*🔑 \*PIN:\*/g, "\n🔑 *PIN:*")
  .replace(/\s*📅 \*Vence:\*/g, "\n📅 *Vence:*")

  // Limpiar saltos duplicados
  .replace(/\n{3,}/g, "\n\n")
  .trim();

// Si es FLUJOTV, eliminar cualquier línea de PIN
if (servicio === "FLUJOTV") {
  mensajeBase = mensajeBase
    .replace(/^🔑 \*PIN:\*.*$/gmi, "")
    .replace(/\n{2,}/g, "\n")
