// Link real largo para WhatsApp
const linkWhatsapp = `https://wa.me/${numeroWhatsapp}?text=${mensajeCodificado}`;

// Link visible en Telegram: se ve solo el número, pero abre el wa.me largo
const linkWhatsappTelegram = `[${numeroWhatsapp}](${linkWhatsapp})`;

// Mensaje final para Telegram
const mensajeTelegram = `${mensajeParaWhatsapp}

📲 *WhatsApp Cliente:* ${linkWhatsappTelegram}`;

return [
  {
    json: {
      mensajeTelegram,
      mensajeParaWhatsapp,
      numeroOriginal,
      numeroWhatsapp,
      linkWhatsapp,
      linkWhatsappTelegram,
      servicio,
      tieneAvisoCambio,
    },
  },
];

const items = $input.all();

// Filtrar solo items reales que tengan datos útiles
const cuentasEncontradas = items.filter(item => {
  const j = item.json;

  return (
    j &&
    (
      j["CORREO"] ||
      j["CONTRASEÑA"] ||
      j["PERFIL"] ||
      j["FECHA QUE ACABA"] ||
      j["NUMERO"]
    )
  );
});

// Si no encontró ninguna cuenta
if (cuentasEncontradas.length === 0) {
  throw new Error("CLIENTE_NO_EXISTE");
}

// Si encontró una sola cuenta, renovar directo
if (cuentasEncontradas.length === 1) {
  const cuenta = cuentasEncontradas[0].json;

  return [
    {
      json: {
        ...cuenta,
        resultado_renovacion: "RENOVAR_DIRECTO",
        total_cuentas: 1
      }
    }
  ];
}

// Si encontró varias cuentas, armar opciones para que elijas cuál renovar
