  return encodeURIComponent(texto).replace(/[!'()*]/g, function (c) {
    return "%" + c.charCodeAt(0).toString(16).toUpperCase();
  });
}

function normalizarNumeroWhatsapp(numeroRaw) {
  let numero = String(numeroRaw || "").replace(/\D/g, "");

  // Venezuela con 0 inicial: 04141264402 -> 584141264402
  if (numero.startsWith("0") && numero.length === 11) {
    numero = "58" + numero.slice(1);
  }

  // Venezuela sin 58: 4141264402 -> 584141264402
  else if (
    numero.length === 10 &&
    (
      numero.startsWith("412") ||
      numero.startsWith("414") ||
      numero.startsWith("416") ||
      numero.startsWith("422") ||
      numero.startsWith("424") ||
      numero.startsWith("426")
    )
  ) {
    numero = "58" + numero;
  }

  return numero;
}

function obtenerDiaVence(fechaStr) {
  if (!fechaStr) return "";

  const partes = String(fechaStr).trim().split(/[\/\-]/);
  if (partes.length < 1) return "";

  return String(Number(partes[0]));
}

function limpiarPerfilNetflix(perfilRaw) {
  const texto = String(perfilRaw || "").trim();
  const textoMayus = texto.toUpperCase();

  // Si es cuenta completa, dejarlo como cuenta completa
  if (textoMayus.includes("CUENTA COMPLETA")) {
    return "Cuenta completa";
  }

  // Si dice perfil extra, siempre perfil 1
  if (textoMayus.includes("PERFIL EXTRA")) {
    return "1";
  }

  // Buscar números dentro de paréntesis: (1), (2), (3), etc.
  const perfiles = [...texto.matchAll(/\((\d+)\)/g)].map(m => m[1]);

  if (perfiles.length > 0) {
    const unicos = [...new Set(perfiles)];

    if (unicos.length === 1) {
      return unicos[0];
    }

    if (unicos.length === 2) {
      return `${unicos[0]} y ${unicos[1]}`;
    }

    return `${unicos.slice(0, -1).join(", ")} y ${unicos[unicos.length - 1]}`;
  }

  // Si no hay paréntesis, quitar textos tipo "1 PERFIL"
  const limpio = texto
    .replace(/\b\d+\s*PERFIL(?:ES)?\b/gi, "")
    .replace(/\bPERFIL(?:ES)?\b/gi, "")
    .replace(/[()]/g, "")
    .replace(/\s+/g, " ")
    .trim();

  return limpio || texto;
}

return items.map(item => {
  const json = item.json;

  const correo = json["CORREO"] || "";
  const contrasena = json["CONTRASEÑA"] || "";
  const perfilRaw = json["PERFIL"] || "";
