    json["VENCE"] ||
    json["vence"] ||
    "";

  const numeroLimpioOriginal = String(numeroRaw || "").replace(/\D/g, "");
  const numeroWhatsapp = normalizarNumeroWhatsapp(numeroRaw);

  // PIN Netflix: últimos 4 dígitos del número
  const pin = numeroLimpioOriginal.slice(-4);

  // Perfil limpio: 1 PERFIL (2) -> 2
  const perfil = limpiarPerfilNetflix(perfilRaw);

  const diaVence = obtenerDiaVence(fechaVence);

  const mensajeParaWhatsapp = `*✨DIAS AGREGADOS A SU SERVICIO✨*

*Datos de Ingreso - NETFLIX*

👤Correo: ${correo}
🔒Contraseña: ${contrasena}
🎞Perfil: ${perfil}
🔒Pin: ${pin}

Vence todos los *${diaVence} de cada Mes.*

