  const mensajeCodificado = encodeUrlSeguro(mensajeParaWhatsapp);
  const linkWhatsapp = `https://wa.me/${numeroWhatsapp}?text=${mensajeCodificado}`;
  const linkWhatsappTelegram = `[${numeroWhatsapp}](${linkWhatsapp})`;

  const mensajeTelegram = `${mensajeParaWhatsapp}

📲 *WhatsApp Cliente:* ${linkWhatsappTelegram}`;

  return {
    json: {
      ...json,
      servicio: "NETFLIX",
      correo,
      contrasena,
      perfilOriginal: perfilRaw,
      perfilLimpio: perfil,
      perfil,
      pin,
      numeroOriginal: numeroLimpioOriginal,
      numeroWhatsapp,
      fechaVence,
      diaVence,
      mensajeParaWhatsapp,
