let mensajeServicios = `He consultado nuestra base de datos y he encontrado los siguientes servicios asociados:\n\n*SERVICIOS ENCONTRADOS:*\n\n`;

// Mensaje 2: El texto consolidado que va para tu Bot
let mensaje_bot = `Opciones disponibles para procesar:\n\n`;

const opcionesOrganizadas = opciones.map((op, index) => {
