const items = $input.all();

function parseOutput(output) {
  if (!output) return {};

  if (typeof output === "object") {
    return output;
  }

  if (typeof output === "string") {
    try {
      return JSON.parse(output);
    } catch (error) {
      throw new Error("OUTPUT_IA_INVALIDO");
    }
  }

  return {};
}

function parseFecha(fechaStr) {
  if (!fechaStr) return null;

  const partes = String(fechaStr).trim().split(/[\/\-]/);

  if (partes.length !== 3) return null;

  const dia = Number(partes[0]);
  const mes = Number(partes[1]) - 1;
  const anio = Number(partes[2]);

  if (!dia || isNaN(mes) || !anio) return null;

  return new Date(anio, mes, dia);
}

function formatFecha(fecha) {
  const dia = String(fecha.getDate()).padStart(2, "0");
  const mes = String(fecha.getMonth() + 1).padStart(2, "0");
  const anio = fecha.getFullYear();

  return `${dia}/${mes}/${anio}`;
}

// Fecha actual Venezuela usando UTC -4
// Así cambia de día a las 12:00 AM de Venezuela, no a las 8:00 PM.
function fechaHoyVenezuela() {
  const ahora = new Date();

  // Venezuela es UTC-4, por eso restamos 4 horas al tiempo UTC
  const fechaVzlaMs = ahora.getTime() - (4 * 60 * 60 * 1000);
  const fechaVzla = new Date(fechaVzlaMs);

  const dia = String(fechaVzla.getUTCDate()).padStart(2, "0");
  const mes = String(fechaVzla.getUTCMonth() + 1).padStart(2, "0");
  const anio = fechaVzla.getUTCFullYear();

  return `${dia}/${mes}/${anio}`;
}

