    json["FECHA QUE ACABA"] ||
    json["VENCE"] ||
    json["vence"] ||
    "";

  if (!rowNumber) {
    throw new Error("ROW_NUMBER_NO_ENCONTRADO");
  }

  if (!mesesAgregar && !diasAgregar) {
    throw new Error(JSON.stringify({
      etiqueta: "PEDIR_TIEMPO_RENOVACION",
      row_number: rowNumber,
      tipo_servicio: tipoServicio,
      NUMERO: numero,
      fecha_actual_vencimiento: fechaActualStr,
      mensajeTelegram: "¿Cuánto tiempo deseas agregarle al cliente?\n\nEjemplo:\nrenovar 1 mes\nrenovar 2 meses\nrenovar 30 días"
    }));
  }

  if (!fechaActualStr) {
    throw new Error(JSON.stringify({
      etiqueta: "FECHA_ACTUAL_NO_ENCONTRADA",
      row_number: rowNumber,
      tipo_servicio: tipoServicio,
      NUMERO: numero
    }));
  }

  const fechaActual = parseFecha(fechaActualStr);

  if (!fechaActual) {
    throw new Error(JSON.stringify({
      etiqueta: "FECHA_ACTUAL_INVALIDA",
      row_number: rowNumber,
      tipo_servicio: tipoServicio,
      NUMERO: numero,
      fecha_recibida: fechaActualStr
    }));
  }

  // Fecha de inicio tomada según Venezuela
  const fechaInicioRenovacion = fechaHoyVenezuela();

  // La nueva fecha SIEMPRE parte desde la fecha actual de vencimiento.
  const nuevaFecha = new Date(fechaActual);

  if (mesesAgregar > 0) {
    nuevaFecha.setMonth(nuevaFecha.getMonth() + mesesAgregar);
  }

  if (diasAgregar > 0) {
    nuevaFecha.setDate(nuevaFecha.getDate() + diasAgregar);
  }

  const nuevaFechaVencimiento = formatFecha(nuevaFecha);

  return {
    json: {
      ...json,
      ...datosIA,
      row_number: rowNumber,
      tipo_servicio: tipoServicio,
      NUMERO: numero,
      numero,
      numero_cliente: numero,
      meses_agregar: mesesAgregar,
      dias_agregar: diasAgregar,
      fecha_anterior: fechaActualStr,
      fecha_inicio_renovacion: fechaInicioRenovacion,
      nueva_fecha_vencimiento: nuevaFechaVencimiento,
      resultado_calculo_renovacion: "CALCULO_OK"
    }
  };
