let output =
  $json.output ||
  $json.text ||
  $json.response ||
  $json.message ||
  "";

output = String(output || "").trim();


// ======================================================
// RESPUESTA CONTROLADA
// ======================================================

function respuestaControlada(
  etiqueta,
  mensajeTelegram,
  extra = {}
) {

  return [
    {
      json: {
        ES_ERROR_CONTROLADO: true,
        etiqueta,
        mensajeTelegram,
        ...extra
      }
    }
  ];
}


// ======================================================
// OUTPUT VACÍO
// ======================================================

if (!output) {

  return respuestaControlada(
    "NO_ENTENDI",
    "No entendí cuál cuenta deseas renovar. Responde con una opción, por ejemplo: 1, 2, la opción 1, 1 y 2, todas, Netflix o FlujoTV."
  );
}


// ======================================================
// NO_ENTENDI
// ======================================================

const outputMayus =
  output
    .trim()
    .toUpperCase();


if (
  outputMayus === "NO_ENTENDI"
) {

  return respuestaControlada(
    "NO_ENTENDI",
    "No entendí cuál cuenta deseas renovar. Responde con una opción válida, por ejemplo: 1, 2, la opción 1, 1 y 2, todas, Netflix o FlujoTV."
  );
}


// ======================================================
// SEPARAR LÍNEAS
// ======================================================

const lineas =
  output
    .split(/\r?\n/)
    .map(
      linea =>
        linea.trim()
    )
    .filter(
      linea =>
        linea.length > 0
    );


const nuevosItems = [];
const cuentasSinTiempo = [];


// ======================================================
// CONVERTIR TIEMPO
// ======================================================

function convertirTiempo(
  tiempoRaw
) {

  const tiempo =
    String(
      tiempoRaw || ""
    )
      .toLowerCase()
      .trim();


  let meses_solicitados = 0;
  let dias_solicitados = 0;


  if (!tiempo) {

    return {
      meses_solicitados,
      dias_solicitados
    };
  }


  const numerosTexto = {

    "un": 1,
    "uno": 1,
    "una": 1,

    "dos": 2,
    "tres": 3,
    "cuatro": 4,
    "cinco": 5,
    "seis": 6,
    "siete": 7,
    "ocho": 8,
    "nueve": 9,
    "diez": 10,
    "once": 11,
    "doce": 12,

    "quince": 15,
    "treinta": 30
  };


  // ====================================================
  // NÚMEROS
  // ====================================================

  const matchDias =
    tiempo.match(
      /(\d+)\s*(dia|dias|día|días)/i
    );


  const matchMeses =
    tiempo.match(
      /(\d+)\s*(mes|meses)/i
    );


  const matchAnio =
    tiempo.match(
      /(\d+)\s*(año|años|ano|anos)/i
    );


  if (matchDias) {

    dias_solicitados =
      Number(
        matchDias[1]
      );
  }


  if (matchMeses) {

    meses_solicitados =
      Number(
        matchMeses[1]
      );
  }


  if (matchAnio) {

    meses_solicitados =
      Number(
        matchAnio[1]
      ) * 12;
  }


  // ====================================================
  // DÍAS EN LETRAS
  // ====================================================

  if (!matchDias) {

    for (
      const [palabra, valor]
      of Object.entries(
        numerosTexto
      )
    ) {

      const regex =
        new RegExp(
          `\\b${palabra}\\b\\s*(dia|dias|día|días)`,
          "i"
        );


      if (
        regex.test(
          tiempo
        )
      ) {

        dias_solicitados =
          valor;

        break;
      }
    }
  }


  // ====================================================
  // MESES EN LETRAS
  // ====================================================

  if (!matchMeses) {

    for (
      const [palabra, valor]
      of Object.entries(
        numerosTexto
      )
    ) {

      const regex =
        new RegExp(
          `\\b${palabra}\\b\\s*(mes|meses)`,
          "i"
        );


      if (
        regex.test(
          tiempo
        )
      ) {

        meses_solicitados =
          valor;

        break;
      }
    }
  }


  // ====================================================
  // AÑOS EN LETRAS
  // ====================================================

  if (!matchAnio) {

    for (
      const [palabra, valor]
      of Object.entries(
        numerosTexto
      )
    ) {

      const regex =
        new RegExp(
          `\\b${palabra}\\b\\s*(año|años|ano|anos)`,
          "i"
        );


      if (
        regex.test(
          tiempo
        )
      ) {

        meses_solicitados =
          valor * 12;

        break;
      }
    }
  }


  return {
    meses_solicitados,
    dias_solicitados
  };
}


// ======================================================
// PROCESAR CADA CUENTA
// ======================================================

for (
  const linea of lineas
) {

  const partes =
    linea
      .split("|")
      .map(
        parte =>
          parte.trim()
      );


  // ====================================================
  // NUEVO FORMATO:
  //
  // 0 OPCION
  // 1 SERVICIO
  // 2 CORREO
  // 3 PERFIL
  // 4 NOMBRE
  // 5 ROW_NUMBER
  // 6 TIEMPO
  //
  // Debe tener 7 partes.
  // Si TIEMPO está vacío igual debe existir la parte 7.
  // ====================================================

  if (
    partes.length !== 7
  ) {

    return respuestaControlada(
      "FORMATO_INVALIDO",
      "No pude procesar correctamente la selección de renovación.",
      {
        salida_ia:
          output,

        linea_problematica:
          linea,

        cantidad_partes:
          partes.length
      }
    );
  }


  const opcionRaw =
    partes[0] || "";


  const servicioRaw =
    partes[1] || "";


  const correo =
    partes[2] || "";


  const perfil =
    partes[3] || "";


  const nombre =
    partes[4] || "";


  const rowNumberRaw =
    partes[5] || "";


  const tiempoRaw =
    partes[6] || "";


  // ====================================================
  // OPCIÓN
  // ====================================================

  const opcion =
    Number(
      opcionRaw
    );


  if (
    !Number.isFinite(opcion) ||
    opcion <= 0
  ) {

    return respuestaControlada(
      "FORMATO_INVALIDO",
      "No pude procesar correctamente la opción seleccionada.",
      {
        salida_ia:
          output,

        opcionRaw
      }
    );
  }


  // ====================================================
  // ROW NUMBER
  // ====================================================

  const rowNumber =
    Number(
      rowNumberRaw
    );


  if (
    !Number.isFinite(rowNumber) ||
    rowNumber <= 0
  ) {

    return respuestaControlada(
      "FORMATO_INVALIDO",
      "No pude reconocer el row_number de la cuenta seleccionada.",
      {
        salida_ia:
          output,

        row_number_recibido:
          rowNumberRaw
      }
    );
  }


  // ====================================================
  // SERVICIO
  // ====================================================

  let tipoServicio =
    String(
      servicioRaw || ""
    )
      .trim()
      .toUpperCase();


  if (
    tipoServicio.includes(
      "NETFLIX"
    )
  ) {

    tipoServicio =
      "NETFLIX";
  }

  else if (
    tipoServicio.includes(
      "FLUJOTV"
    ) ||
    tipoServicio.includes(
      "FLUJO TV"
    ) ||
    tipoServicio.includes(
      "FLUJO"
    )
  ) {

    tipoServicio =
      "FLUJOTV";
  }

  else {

    return respuestaControlada(
      "FORMATO_INVALIDO",
      "No pude reconocer el servicio seleccionado.",
      {
        salida_ia:
          output,

        servicioRaw
      }
    );
  }


  // ====================================================
  // CONVERTIR TIEMPO
  // ====================================================

  const {
    meses_solicitados,
    dias_solicitados
  } =
    convertirTiempo(
      tiempoRaw
    );


  // ====================================================
  // CUENTA BASE
  // ====================================================

  const cuentaBase = {

    opcion,

    tipo_servicio:
      tipoServicio,

    CORREO:
      correo,

    PERFIL:
      perfil,

    NOMBRE:
      nombre,

    row_number:
      rowNumber,

    ROW_NUMBER:
      rowNumber,

    tiempo_raw:
      tiempoRaw,

    seleccion_renovacion:
      true
  };


  // ====================================================
  // FALTA TIEMPO
  //
  // Ejemplo:
  //
  // 2|FLUJOTV|cmaxnet105|1 PERFIL|edward gang|40|
  // ====================================================

  if (
    !meses_solicitados &&
    !dias_solicitados
  ) {

    cuentasSinTiempo.push(
      cuentaBase
    );

    continue;
  }


  // ====================================================
  // CUENTA CORRECTA
  // ====================================================

  nuevosItems.push({
    json: {

      etiqueta:
        "OK",

      ES_ERROR_CONTROLADO:
        false,

      ...cuentaBase,

      meses_solicitados,

      dias_solicitados
    }
  });
}


// ======================================================
// FALTA MES / TIEMPO
// ======================================================

if (
  cuentasSinTiempo.length > 0
) {

  return respuestaControlada(
    "FALTA_MES",

    "Perfecto. ¿Cuánto tiempo deseas agregarle?\n\nEjemplo:\n1 mes\n2 meses\n6 meses\n30 días",

    {
      total_cuentas:
        cuentasSinTiempo.length,

      cuentas_seleccionadas:
        cuentasSinTiempo,

      ULTIMA_SELECCION_RENOVACION:
        JSON.stringify(
          cuentasSinTiempo
        )
    }
  );
}


// ======================================================
// SEGURIDAD
// ======================================================

if (
  nuevosItems.length === 0
) {

  return respuestaControlada(
    "FORMATO_INVALIDO",

    "No pude procesar correctamente la selección de renovación.",

    {
      salida_ia:
        output
    }
  );
}


// ======================================================
// SALIDA BUENA
// ======================================================

return nuevosItems;

