const items = $input.all();

function encodeUrlSeguro(texto) {
  return encodeURIComponent(texto).replace(/[!'()*]/g, function (c) {
    return "%" + c.charCodeAt(0).toString(16).toUpperCase();
  });
}

function normalizarNumeroWhatsapp(numeroRaw) {
  let numero = String(numeroRaw || "").replace(/\D/g, "");

  // Venezuela con 0 inicial: 04141264402 -> 584141264402
  if (numero.startsWith("0") && numero.length === 11) {
    numero = "58" + numero.slice(1);
  }

  // Venezuela sin 58: 4141264402 -> 584141264402
  else if (
    numero.length === 10 &&
    (
      numero.startsWith("412") ||
      numero.startsWith("414") ||
      numero.startsWith("416") ||
      numero.startsWith("424") ||
      numero.startsWith("426")
    )
  ) {
    numero = "58" + numero;
  }

  return numero;
}

function obtenerDiaVence(fechaStr) {
  if (!fechaStr) return "";

  const partes = String(fechaStr).trim().split(/[\/\-]/);
  if (partes.length < 1) return "";

  return String(Number(partes[0]));
}

function limpiarPerfilNetflix(perfilRaw) {
  const texto = String(perfilRaw || "").trim();
  const textoMayus = texto.toUpperCase();

  // Si es cuenta completa, dejarlo como cuenta completa
  if (textoMayus.includes("CUENTA COMPLETA")) {
    return "Cuenta completa";
  }

  // Si dice perfil extra, siempre perfil 1
  if (textoMayus.includes("PERFIL EXTRA")) {
    return "1";
  }

  // Buscar números dentro de paréntesis: (1), (2), (3), etc.
  const perfiles = [...texto.matchAll(/\((\d+)\)/g)].map(m => m[1]);

  if (perfiles.length > 0) {
    const unicos = [...new Set(perfiles)];

    if (unicos.length === 1) {
      return unicos[0];
    }

    if (unicos.length === 2) {
      return `${unicos[0]} y ${unicos[1]}`;
    }

    return `${unicos.slice(0, -1).join(", ")} y ${unicos[unicos.length - 1]}`;
  }

  // Si no hay paréntesis, quitar textos tipo "1 PERFIL"
  const limpio = texto
    .replace(/\b\d+\s*PERFIL(?:ES)?\b/gi, "")
    .replace(/\bPERFIL(?:ES)?\b/gi, "")
    .replace(/[()]/g, "")
    .replace(/\s+/g, " ")
    .trim();

  return limpio || texto;
}

return items.map(item => {
  const json = item.json;

  const correo = json["CORREO"] || "";
  const contrasena = json["CONTRASEÑA"] || "";
  const perfilRaw = json["PERFIL"] || "";
  const numeroRaw = json["NUMERO"] || "";
  const fechaVence =
    json["FECHA QUE ACABA"] ||
    json["nueva_fecha_vencimiento"] ||
    json["fecha_actual_vencimiento"] ||
    json["VENCE"] ||
    json["vence"] ||
    "";

  const numeroLimpioOriginal = String(numeroRaw || "").replace(/\D/g, "");
  const numeroWhatsapp = normalizarNumeroWhatsapp(numeroRaw);

  // PIN Netflix: últimos 4 dígitos del número
  const pin = numeroLimpioOriginal.slice(-4);

  // Perfil limpio: 1 PERFIL (2) -> 2
  const perfil = limpiarPerfilNetflix(perfilRaw);

  const diaVence = obtenerDiaVence(fechaVence);

  const mensajeParaWhatsapp = `*✨DIAS AGREGADOS A SU SERVICIO✨*

*Datos de Ingreso - NETFLIX*

👤Correo: ${correo}
🔒Contraseña: ${contrasena}
🎞Perfil: ${perfil}
🔒Pin: ${pin}

Vence todos los *${diaVence} de cada Mes.*

*🚨Atención!!* le recomendamos que *nos guarde en su lista de contactos y nos recomiende con amigos y familiares* para obtener *descuentos exclusivos*, y podrá ver nuestros estados de WhatsApp y enterarse de las *últimas novedades y promociones.*`;

  const mensajeCodificado = encodeUrlSeguro(mensajeParaWhatsapp);
  const linkWhatsapp = `https://wa.me/${numeroWhatsapp}?text=${mensajeCodificado}`;
  const linkWhatsappTelegram = `[${numeroWhatsapp}](${linkWhatsapp})`;

  const mensajeTelegram = `${mensajeParaWhatsapp}

📲 *WhatsApp Cliente:* ${linkWhatsappTelegram}`;

  return {
    json: {
      ...json,
      servicio: "NETFLIX",
      correo,
      contrasena,
      perfilOriginal: perfilRaw,
      perfilLimpio: perfil,
      perfil,
      pin,
      numeroOriginal: numeroLimpioOriginal,
      numeroWhatsapp,
      fechaVence,
      diaVence,
      mensajeParaWhatsapp,
      linkWhatsapp,
      linkWhatsappTelegram,
      mensajeTelegram
    }
  };
});

const items = $input.all();

function encodeUrlSeguro(texto) {
  return encodeURIComponent(texto).replace(/[!'()*]/g, function (c) {
    return "%" + c.charCodeAt(0).toString(16).toUpperCase();
  });
}

function normalizarNumeroWhatsapp(numeroRaw) {
  let numero = String(numeroRaw || "").replace(/\D/g, "");

  // Venezuela con 0 inicial: 04141264402 -> 584141264402
  if (numero.startsWith("0") && numero.length === 11) {
    numero = "58" + numero.slice(1);
  }

  // Venezuela sin 58: 4141264402 -> 584141264402
  else if (
    numero.length === 10 &&
    (
      numero.startsWith("412") ||
      numero.startsWith("414") ||
      numero.startsWith("416") ||
      numero.startsWith("424") ||
      numero.startsWith("426")
    )
  ) {
    numero = "58" + numero;
  }

  return numero;
}

function obtenerDiaVence(fechaStr) {
  if (!fechaStr) return "";

  const partes = String(fechaStr).trim().split(/[\/\-]/);
  if (partes.length < 1) return "";

  return String(Number(partes[0]));
}

return items.map(item => {
  const json = item.json;

  const correo = json["CORREO"] || "";
  const contrasena = json["CONTRASEÑA"] || "";
  const perfil = json["PERFIL"] || "";
  const numeroRaw = json["NUMERO"] || "";

  const fechaVence =
    json["FECHA QUE ACABA"] ||
    json["nueva_fecha_vencimiento"] ||
    json["fecha_actual_vencimiento"] ||
    json["VENCE"] ||
    json["vence"] ||
    "";

  const numeroLimpioOriginal = String(numeroRaw || "").replace(/\D/g, "");
  const numeroWhatsapp = normalizarNumeroWhatsapp(numeroRaw);
  const diaVence = obtenerDiaVence(fechaVence);

  const mensajeParaWhatsapp = `*✨DIAS AGREGADOS A SU SERVICIO✨*

*Datos de Ingreso - FLUJOTV*

👤Correo: ${correo}
🔒Contraseña: ${contrasena}
🎞Perfil: ${perfil}

Vence todos los *${diaVence} de cada Mes.*

*🚨Atención!!* le recomendamos que *nos guarde en su lista de contactos y nos recomiende con amigos y familiares* para obtener *descuentos exclusivos*, y podrá ver nuestros estados de WhatsApp y enterarse de las *últimas novedades y promociones.*`;

  const mensajeCodificado = encodeUrlSeguro(mensajeParaWhatsapp);
  const linkWhatsapp = `https://wa.me/${numeroWhatsapp}?text=${mensajeCodificado}`;
  const linkWhatsappTelegram = `[${numeroWhatsapp}](${linkWhatsapp})`;

  const mensajeTelegram = `${mensajeParaWhatsapp}

📲 *WhatsApp Cliente:* ${linkWhatsappTelegram}`;

  return {
    json: {
      ...json,
      servicio: "FLUJOTV",
      correo,
      contrasena,
      perfil,
      numeroOriginal: numeroLimpioOriginal,
      numeroWhatsapp,
      fechaVence,
      diaVence,
      mensajeParaWhatsapp,
      linkWhatsapp,
      linkWhatsappTelegram,
      mensajeTelegram
    }
  };
});

const items = $input.all();

function limpiarNumero(valor) {
  if (valor === undefined || valor === null || valor === "") {
    return null;
  }

  const texto = String(valor).trim();
  const match = texto.match(/-?\d+/);

  if (!match) {
    return null;
  }

  const numero = Number(match[0]);

  if (isNaN(numero)) {
    return null;
  }

  return numero;
}

function textoVencimiento(diasRestantes) {
  if (diasRestantes === 2) {
    return "vence en 2 días";
  }

  if (diasRestantes === 1) {
    return "vence mañana";
  }

  if (diasRestantes <= 0) {
    return "vencida";
  }

  return `vence en ${diasRestantes} días`;
}

function detectarServicioDesdeProveedor(proveedorRaw) {
  const proveedor = String(proveedorRaw || "").toUpperCase();

  // Si dentro del texto aparece NETFLIX
  // Ejemplo: NETFLIX (JPPANEL)
  if (proveedor.includes("NETFLIX")) {
    return "NETFLIX";
  }

  // Si dentro del texto aparece FLUJOTV / FLUJO TV / FLUJO
  if (
    proveedor.includes("FLUJOTV") ||
    proveedor.includes("FLUJO TV") ||
    proveedor.includes("FLUJO")
  ) {
    return "FLUJOTV";
  }

  return "OTRO";
}

const cuentasFiltradas = [];

for (const item of items) {
  const json = item.json;

  const correo =
    json["CORREO"] ||
    json["Correo"] ||
    json["correo"] ||
    "";

  // IMPORTANTE:
  // Usamos ?? porque 0 es un valor válido.
  const diasRaw =
    json["DIAS RESTANTES"] ??
    json["Dias Restantes"] ??
    json["dias restantes"] ??
    json["DIAS_RESTANTES"] ??
    null;

  const proveedor =
    json["PROVEEDOR"] ||
    json["Proveedor"] ||
    json["proveedor"] ||
    json["PROVEEEDOR"] ||
    "";

  const diasRestantes = limpiarNumero(diasRaw);

  // Si no conseguimos un número válido, ignoramos la fila
  if (diasRestantes === null) {
    continue;
  }

  // SOLO cuentas con 2 días o menos
  //
  // 30 -> NO
  // 11 -> NO
  // 3  -> NO
  //
  // 2  -> SÍ
  // 1  -> SÍ
  // 0  -> SÍ
  // -1 -> SÍ
  // -2 -> SÍ
  if (diasRestantes > 2) {
    continue;
  }

  const servicio = detectarServicioDesdeProveedor(proveedor);

  cuentasFiltradas.push({
    correo,
    proveedor,
    diasRestantes,
    vencimiento: textoVencimiento(diasRestantes),
    servicio,
  });
}

// Ordenar:
// 1. NETFLIX
// 2. FLUJOTV
// 3. OTROS
const ordenServicio = {
  NETFLIX: 1,
  FLUJOTV: 2,
  OTRO: 3,
};

cuentasFiltradas.sort((a, b) => {
  const ordenA = ordenServicio[a.servicio] || 99;
  const ordenB = ordenServicio[b.servicio] || 99;

  if (ordenA !== ordenB) {
    return ordenA - ordenB;
  }

  // Dentro del mismo servicio:
  // primero las vencidas, luego 0, 1, 2.
  return a.diasRestantes - b.diasRestantes;
});

// Si no quedó ninguna cuenta
if (cuentasFiltradas.length === 0) {
  return [
    {
      json: {
        hay_alertas: false,
        total_alertas: 0,
        mensajeTelegram:
          "✅ No hay cuentas por pagar a proveedores con 2 días o menos.",
      },
    },
  ];
}

// Separar por servicio
const cuentasNetflix = cuentasFiltradas.filter(
  c => c.servicio === "NETFLIX"
);

const cuentasFlujotv = cuentasFiltradas.filter(
  c => c.servicio === "FLUJOTV"
);

const cuentasOtros = cuentasFiltradas.filter(
  c => c.servicio === "OTRO"
);

// Crear mensaje
let mensaje = `🚨 *CUENTAS POR PAGAR A PROVEEDORES*\n\n`;

function agregarGrupo(titulo, lista) {
  if (lista.length === 0) {
    return "";
  }

  let texto = `*${titulo}*\n\n`;

  lista.forEach((cuenta, index) => {
    texto += `${index + 1}. Correo: ${cuenta.correo || "No encontrado"}\n`;
    texto += `Proveedor: ${cuenta.proveedor || "No encontrado"}\n`;
    texto += `Vencimiento: ${cuenta.vencimiento}\n\n`;
  });

  return texto;
}

// Primero Netflix
mensaje += agregarGrupo(
  "CUENTAS POR PAGAR A PROVEEDOR NETFLIX",
  cuentasNetflix
);

// Después FlujoTV
mensaje += agregarGrupo(
  "CUENTAS POR PAGAR A PROVEEDOR FLUJOTV",
