  });
}


function normalizarNumeroWhatsapp(numeroRaw) {
  let numero = String(numeroRaw || "").replace(/\D/g, "");

  // Venezuela con 0 inicial:
  // 04141264402 -> 584141264402
  if (
    numero.startsWith("0") &&
    numero.length === 11
  ) {
    numero = "58" + numero.slice(1);
  }

  // Venezuela sin 58:
  // 4141264402 -> 584141264402
  else if (
    numero.length === 10 &&
    (
      numero.startsWith("412") ||
      numero.startsWith("414") ||
      numero.startsWith("416") ||
      numero.startsWith("422") ||
      numero.startsWith("424") ||
      numero.startsWith("426")
    )
  ) {
    numero = "58" + numero;
