function parseFecha(fechaStr) {
  if (!fechaStr) return null;

  const partes =
    String(fechaStr)
      .trim()
      .split(/[\/\-]/);

  if (partes.length !== 3) {
    return null;
  }

  const dia =
    Number(partes[0]);

  const mes =
    Number(partes[1]) - 1;

  const anio =
    Number(partes[2]);

  if (
    !dia ||
    isNaN(mes) ||
    !anio
  ) {
    return null;
  }

  return new Date(
    anio,
    mes,
    dia
  );
}


function formatFecha(fecha) {
  const dia =
    String(
      fecha.getDate()
    ).padStart(2, "0");

  const mes =
    String(
      fecha.getMonth() + 1
    ).padStart(2, "0");

  const anio =
    fecha.getFullYear();

  return `${dia}/${mes}/${anio}`;
}


// ======================================================
// FECHA ACTUAL VENEZUELA UTC -4
// ======================================================

function fechaHoyVenezuela() {
  const ahora =
    new Date();

  const fechaVzlaMs =
    ahora.getTime() -
    (4 * 60 * 60 * 1000);

  const fechaVzla =
