    ).padStart(2, "0");

  const mes =
    String(
      fechaVzla.getUTCMonth() + 1
    ).padStart(2, "0");

  const anio =
    fechaVzla.getUTCFullYear();

  return `${dia}/${mes}/${anio}`;
}


