// ======================================================
// HELPERS
// ======================================================

function limpiar(valor) {

  return String(
    valor ?? ""
  ).trim();
}


function numero(valor) {

  if (
    valor === null ||
    valor === undefined ||
    valor === ""
  ) {

    return 0;
  }


  const n =
    Number(
      String(valor)
        .trim()
        .replace(",", ".")
    );


  return Number.isFinite(n)
    ? n
    : 0;
}


function campo(
  fila,
  ...nombres
) {

  for (
    const nombre of nombres
  ) {

    if (
      fila[nombre] !== undefined &&
      fila[nombre] !== null &&
      limpiar(fila[nombre]) !== ""
    ) {

      return limpiar(
        fila[nombre]
      );
    }
  }

  return "";
}


// ======================================================
// ESCAPAR HTML
// ======================================================

function escaparHtml(valor) {

  return limpiar(valor)
    .replace(/&/g, "&amp;")
    .replace(/</g, "&lt;")
    .replace(/>/g, "&gt;")
    .replace(/"/g, "&quot;");
}


// ======================================================
// DETECTAR SERVICIO
//
// Fuente principal:
//
// tipo_servicio = NETFLIX
// tipo_servicio = FLUJOTV
// ======================================================

function detectarServicio(fila) {

  const directo =
    limpiar(
      fila.tipo_servicio ||
      fila.TIPO_SERVICIO ||
      fila.SERVICIO ||
      fila.ORIGEN ||
      ""
    )
      .toUpperCase();


  if (
    directo.includes("NETFLIX")
  ) {

    return "NETFLIX";
  }


  if (
    directo.includes("FLUJOTV") ||
    directo.includes("FLUJO")
  ) {

    return "FLUJOTV";
  }


  // ====================================================
  // FALLBACK
  // ====================================================

  const textoFila =
    JSON.stringify(fila)
      .toUpperCase();


  if (
    textoFila.includes("NETFLIX")
  ) {

    return "NETFLIX";
  }


  if (
    textoFila.includes("FLUJOTV") ||
    textoFila.includes("FLUJO")
  ) {

    return "FLUJOTV";
  }


  return "";
}


// ======================================================
// NORMALIZAR TELÉFONO PARA WA.ME
//
// 04141234567
// → 584141234567
//
// 4141234567
// → 584141234567
//
// +584141234567
// → 584141234567
// ======================================================

function telefonoWhatsapp(valor) {

  let telefono =
    limpiar(valor)
      .replace(/\D/g, "");


  if (
    telefono.startsWith("0") &&
    telefono.length === 11
  ) {

    telefono =
      "58" +
      telefono.slice(1);
  }


  else if (
    telefono.length === 10 &&
    telefono.startsWith("4")
  ) {

    telefono =
      "58" +
      telefono;
  }


  return telefono;
}


// ======================================================
// OBTENER PIN NETFLIX
//
// El PIN son los últimos 4 dígitos
// del número del cliente.
// ======================================================

function obtenerPinNetflix(telefono) {

  const numeroLimpio =
    limpiar(telefono)
      .replace(/\D/g, "");


  if (
    numeroLimpio.length < 4
  ) {

    return "";
  }


  return numeroLimpio.slice(-4);
}


