`📺 <b>NETFLIX</b>

${lineas}`
  );
}


// ------------------------------------------------------
// FLUJOTV
// ------------------------------------------------------

if (
  flujotv.length
) {

  const lineas =
    flujotv
      .map(r =>
        `<a href="${escaparHtml(r.enlace)}">${escaparHtml(r.telefono)}</a>`
      )
      .join("\n");


  secciones.push(
`📡 <b>FLUJOTV</b>

${lineas}`
  );
}


// ======================================================
// MENSAJE FINAL
// ======================================================

const textoMensaje =
`🔐 <b>CAMBIO DE CONTRASEÑA</b>

Cuenta: ${escaparHtml(correoBuscado)}

${secciones.join("\n\n")}`;


// ======================================================
// SALIDA
// ======================================================

return [
  {
    json: {

      CORREO:
        correoBuscado,

      TOTAL_CLIENTES:
        registros.length,

      TOTAL_NETFLIX:
        netflix.length,

      TOTAL_FLUJOTV:
        flujotv.length,

      TEXTO_MENSAJE:
        textoMensaje,

      PARSE_MODE:
        "HTML"
    }
  }
];
